/**
 * @name SSRF vulnerability
 * @description User-controlled input flowing to HTTP request functions could lead to SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // HTTP request functions
    exists(API::CallNode call |
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "options"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("aiohttp").getMember(["ClientSession", "request"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("urllib").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF from $@.", source.getNode(), "user input"

/**
 * @name FSSpec-specific path traversal
 * @description User-controlled paths in fsspec file system operations could lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/fsspec-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module FsspecPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for file operations in fsspec - open, read, write, delete operations
    exists(API::CallNode call |
      // Look for calls to file system methods that take path arguments
      call = API::moduleImport("fsspec").getMember(["open", "read", "write", "delete", "rename"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // Also check for os.path.join operations where the first argument might be controlled
    exists(API::CallNode call |
      call = API::moduleImport("os.path").getMember("join").getACall() and
      sink = call.getArg(0)
    )
  }
}

module FsspecPathTraversalFlow = TaintTracking::Global<FsspecPathTraversalConfig>;
import FsspecPathTraversalFlow::PathGraph

from FsspecPathTraversalFlow::PathNode source, FsspecPathTraversalFlow::PathNode sink
where FsspecPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "FSSpec path traversal from $@.", source.getNode(), "user input"
